function ChapterManager({chapters,onSaved}:{chapters:any[],onSaved:()=>Promise<void>}){const[editing,setEditing]=useState<any>(),[code,setCode]=useState(""),[name,setName]=useState(""),[order,setOrder]=useState(chapters.length+1),[error,setError]=useState(""),[saving,setSaving]=useState(false);function reset(){setEditing(undefined);setCode("");setName("");setOrder(chapters.length+1);setError("")}function edit(chapter:any){setEditing(chapter);setCode(chapter.code);setName(chapter.name);setOrder(chapter.display_order||1);setError("")}async function save(event:React.FormEvent){event.preventDefault();setSaving(true);setError("");try{await api(editing?`/chapters/${editing.id}`:"/chapters",{method:editing?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({code,name,display_order:order})});await onSaved();reset()}catch(e:any){setError(e.message)}finally{setSaving(false)}}async function remove(chapter:any){if(!confirm(`Xóa chương ${chapter.code}?`))return;setError("");try{await api(`/chapters/${chapter.id}`,{method:"DELETE"});if(editing?.id===chapter.id)reset();await onSaved()}catch(e:any){setError(e.message)}}return <div className="chapterManager"><div className="pageTitle"><div><span className="eyebrow">NGÂN HÀNG NỘI DUNG</span><h2>Quản lý chương</h2><p>Chỉnh tên, mã và thứ tự chương. Chương mới sẽ xuất hiện ngay trong form câu hỏi.</p></div></div>{error&&<div className="error">{error}</div>}<div className="chapterManagerGrid"><form className="chapterForm" onSubmit={save}><div className="panelHeading"><div><h3>{editing?"Cập nhật chương":"Thêm chương mới"}</h3><span>Mã chương dùng để nhận diện trong danh sách.</span></div></div><label>Mã chương<input required value={code} onChange={e=>setCode(e.target.value)} placeholder={`CH${chapters.length+1}`}/></label><label>Tên chương<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Tên chương"/></label><label>Thứ tự hiển thị<input required type="number" min="1" value={order} onChange={e=>setOrder(Math.max(1,Number(e.target.value)||1))}/></label><div className="chapterFormActions"><button className="primary" disabled={saving}>{saving?"Đang lưu...":editing?"Lưu thay đổi":"Thêm chương"}</button>{editing&&<button type="button" onClick={reset}>Hủy sửa</button>}</div></form><section className="chapterTablePanel"><div className="panelHeading"><div><h3>Các chương</h3><span>{chapters.length} chương đang hoạt động</span></div></div><div className="chapterRows">{chapters.map(chapter=><div className="chapterRow" key={chapter.id}><span className="chapterOrder">{chapter.display_order}</span><span className="chapterRowName"><b>{chapter.code}</b><small>{chapter.name}</small></span><div className="chapterRowActions"><button className="tableAction" onClick={()=>edit(chapter)}>Sửa</button><button className="tableAction dangerAction" onClick={()=>remove(chapter)}>Xóa</button></div></div>)}</div></section></div></div>}
function Preferences({density,onChange}:{density:string,onChange:(value:string)=>void}){const[theme,setTheme]=useState(()=>localStorage.getItem("math-bank-theme")==="dark"?"dark":"light");useEffect(()=>{if(density==="compact")onChange("comfortable")},[density,onChange]);function toggle(){const next=theme==="dark"?"light":"dark";setTheme(next);onChange("comfortable");localStorage.setItem("math-bank-theme",next);document.documentElement.dataset.theme=next}return <div className="preferencesPage"><div className="pageTitle"><div><span className="eyebrow">TÙY CHỌN</span><h2>Giao diện</h2><p>Tùy chỉnh cách hiển thị trên thiết bị này.</p></div></div><section className="preferencePanel"><div><h3>Chế độ hiển thị</h3><p>Chuyển đổi giao diện sáng và tối.</p></div><button type="button" className="themeSwitch" role="switch" aria-checked={theme==="dark"} onClick={toggle}><span className="themeSwitchTrack"><i/></span><b>{theme==="dark"?"Tối":"Sáng"}</b></button></section></div>}
function ThemeToggle(){const[theme,setTheme]=useState(()=>localStorage.getItem("math-bank-theme")==="dark"?"dark":"light");function toggle(){const next=theme==="dark"?"light":"dark";setTheme(next);localStorage.setItem("math-bank-theme",next);document.documentElement.dataset.theme=next}return <button type="button" className="themeSwitch sidebarThemeToggle" role="switch" aria-label="Chuyển chế độ giao diện" aria-checked={theme==="dark"} onClick={toggle}><span className="themeSwitchTrack"><i/></span><b>{theme==="dark"?"Tối":"Sáng"}</b></button>}
function DatabaseOverview({go}:{go:(page:string)=>void}){
	const[data,setData]=useState<any>(),[error,setError]=useState("");
	useEffect(()=>{api("/inspector").then(setData).catch(e=>setError(e.message))},[]);
	const items=[["questions","Câu hỏi","☷"],["priority_questions","Câu hỏi ưu tiên","★"],["chapters","Chương","▦"],["exams","Đề thi","▣"],["used_questions","Câu đã xuất hiện trong đề","✓"],["unused_questions","Câu chưa từng ra đề","○"],["confirmed_answers","Đáp án đã xác nhận","✓"],["unconfirmed_answers","Chưa xác nhận","!"],["questions_without_answers","Chưa có đáp án","○"]],difficulties=data?.questions_by_difficulty||[],chapters=data?.questions_by_chapter||[],answerStatuses=data?.questions_by_answer_status||[],maxChapter=Math.max(1,...chapters.map((chapter:any)=>chapter.count)),questionCount=data?.questions||0,answerColors={confirmed:"#27a96f",unconfirmed:"#d88d18",missing:"#d44b5d"} as Record<string,string>;
	return <div className="inspector"><div className="pageTitle"><div><span className="eyebrow">DỮ LIỆU</span><h2>Tổng quan database</h2><p>Tình trạng ngân hàng, mức độ sử dụng và trạng thái đáp án của câu hỏi.</p></div><button className="ghostButton" onClick={()=>go("questions")}>Mở danh sách câu hỏi →</button></div>{error&&<div className="error">{error}</div>}<div className="databaseGrid">{items.map(([key,label,icon])=><div className="databaseCard" key={key}><span className="databaseIcon">{icon}</span><span><b>{data?.[key]??"-"}</b><small>{label}</small></span></div>)}</div><div className="databaseCharts"><section className="databasePanel"><div className="panelHeading"><div><h3>Câu hỏi theo độ khó</h3><span>{questionCount} câu hỏi đang hoạt động</span></div></div>{difficulties.map((item:any,index:number)=><div className="databaseBarRow" key={item.id}><div><span><i style={{background:["#159463","#bd7b12","#d44b5d"][index%3]}}/>{item.name}</span><b>{item.count}</b></div><div className="barTrack"><i style={{width:`${questionCount?item.count/questionCount*100:0}%`,background:["#159463","#bd7b12","#d44b5d"][index%3]}}/></div></div>)}</section><section className="databasePanel"><div className="panelHeading"><div><h3>Câu hỏi theo chương</h3><span>{chapters.length} chương</span></div></div>{chapters.map((chapter:any)=><div className="databaseBarRow" key={chapter.id}><div><span><b className="databaseChapterCode">{chapter.code}</b>{chapter.name}</span><b>{chapter.count}</b></div><div className="barTrack"><i style={{width:`${chapter.count?Math.max(3,chapter.count/maxChapter*100):0}%`,background:"#27a96f"}}/></div></div>)}</section><section className="databasePanel answerStatusChart"><div className="panelHeading"><div><h3>Tình trạng đáp án</h3><span>{questionCount} câu hỏi, mỗi câu thuộc một trạng thái</span></div></div>{answerStatuses.map((item:any)=><div className="databaseBarRow" key={item.id}><div><span><i style={{background:answerColors[item.id]||"#748398"}}/>{item.name}</span><b>{item.count}</b></div><div className="barTrack"><i style={{width:`${questionCount?item.count/questionCount*100:0}%`,background:answerColors[item.id]||"#748398"}}/></div></div>)}</section></div></div>
}
